// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // Fuzz parameters: caller (the `from` argument), value v, and a single recipient tos0
    function testFuzz_property(address from, uint8 v, address tos0) public {
        // Keep domain wide but avoid the zero-address receiver which may be undesirable for some callees
        // and ensure tos0 is not the same as address(0) to make the call meaningful.
        vm.assume(tos0 != address(0));

        // Deploy a recorder that implements transferFrom(address,address,uint256)
        // It will record number of times transferFrom was invoked and the last recorded args.
        Recorder rec = new Recorder();

        // Build a single-element recipients array
        address[] memory tos = new address[](1);
        tos[0] = tos0;

        // We call c.transfer; if it reverts we'll treat that as test-run failure for this input
        bool ok;
        try c.transfer(from, address(rec), tos, uint256(v)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct C always calls transferFrom on the callee with the selector for transferFrom(...)
        // for each recipient. For our single-recipient case, recorder should have exactly one recording
        // and the recorded args should match (from, tos0, v). We assert that this holds whenever the call
        // completed successfully. This is a universal property over admissible inputs; the mutant that uses
        // the wrong selector will not invoke transferFrom and thus the recorder will show zero calls for some inputs.

        if (ok) {
            // Read recorder's public getters
            uint256 count = rec.callCount();
            address lastFrom = rec.lastFrom();
            address lastTo = rec.lastTo();
            uint256 lastV = rec.lastV();

            // Exactly one external transferFrom call must have been recorded with matching arguments
            assertTrue(count == 1 && lastFrom == from && lastTo == tos0 && lastV == uint256(v));
        } else {
            // If C.transfer reverted, then the property about successful completion does not need to hold.
            // We still assert that ok is true for the reference on-all-inputs; but to keep the test robust and
            // allow any reverts that can happen legitimately, we just require ok==true here so the reference
            // must not revert for these inputs. However, to satisfy the requirement that the test PASS on the
            // reference for ALL inputs, we avoid constraining the inputs too much; if reference never reverts,
            // this branch won't be taken. To keep a single assertion as required, simply assertTrue(ok) is not
            // used here to allow the recorder-based property to be the single observable assertion for successful calls.
            // Therefore, we make no assertion in the revert branch.
        }
    }
}

// Recorder that implements transferFrom(address,address,uint256)
contract Recorder {
    uint256 public callCount;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // This function matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        callCount += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }

    // Catch-all to not revert if mutant calls a different selector; do nothing so mutant won't record transferFrom
    fallback() external payable {}
}
